<?php
declare(strict_types=1);
header('Content-Type: application/json; charset=utf-8');
define('SMART_AI_INTERNAL', true);
require __DIR__ . '/ai-config.php';
function smart_ai_json(array $data): void { echo json_encode($data, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE); exit; }
function smart_ai_log(string $message): void { $dir=__DIR__.'/logs'; if(!is_dir($dir)){@mkdir($dir,0755,true);} @file_put_contents($dir.'/ai-error.log','['.date('Y-m-d H:i:s').'] '.$message.PHP_EOL,FILE_APPEND); }
function smart_ai_file(string $path): string { if(!file_exists($path)){return '';} $c=file_get_contents($path); return is_string($c)?trim($c):''; }
function smart_ai_php_text(string $path): string { if(!file_exists($path)){return '';} ob_start(); $r=include $path; $b=trim((string)ob_get_clean()); return is_string($r)&&trim($r)!==''?trim($r):$b; }
function smart_ai_folder(string $folder): string { $out=''; if(!is_dir($folder)){return '';} $files=glob($folder.'/*.txt'); if(!is_array($files)){return '';} foreach($files as $f){$c=smart_ai_file($f); if($c!==''){$out.="\n\nFILE: ".basename($f)."\n".$c;}} return trim($out); }
function smart_ai_detect_mode(string $message): string { $m=strtolower($message); foreach(['estimate','price','pricing','cost','quote','how much','sq ft','square foot','linear foot','labor','material','deck','paint','roof','plumbing','electrical','bathroom','kitchen','remodel'] as $w){ if(strpos($m,$w)!==false){return 'estimating';}} return 'customer_service'; }
function smart_ai_local_reply(string $message,string $mode,string $booking): string { $m=strtolower($message); if($mode==='appointment'||strpos($m,'appointment')!==false||strpos($m,'book')!==false){return 'You can book an appointment with Smart Choice Contractors USA here: '.$booking.' You may also call (727) 755-3786.';} if($mode==='estimating'||strpos($m,'price')!==false||strpos($m,'cost')!==false||strpos($m,'estimate')!==false){return 'I can help with a preliminary estimate. Please send the service type, project address or city, measurements or square footage, photos if available, material preference, access conditions, and timeline. Final pricing requires field verification and written approval. Appointment: '.$booking;} return 'Smart Choice Contractors USA provides remodeling, plumbing, electrical, roofing, flooring, painting, drywall, kitchens, bathrooms, decks, windows and doors, concrete, fencing, engineering support, project planning, permitting support, estimates, and customer support across Tampa Bay and nearby Florida areas. How can I help with your project?'; }
function smart_ai_prompt(string $mode): string { global $SMART_COMPANY_NAME,$SMART_COMPANY_PHONE,$SMART_COMPANY_EMAIL,$SMART_WEBSITE,$SMART_BOOKING_LINK; $customer=smart_ai_php_text(__DIR__.'/customer-service.php'); $estimate=smart_ai_php_text(__DIR__.'/ai.php'); $knowledge=smart_ai_folder(__DIR__.'/knowledge'); $site=smart_ai_file(__DIR__.'/data/site-knowledge.txt'); return "You are the Smart Choice Contractors USA website AI assistant. Use Smart Choice company and website info first. Help with services, customer support, project questions, appointment guidance, and preliminary estimating. Never provide a binding quote. Ask for missing details. Company: {$SMART_COMPANY_NAME}. Phone: {$SMART_COMPANY_PHONE}. Email: {$SMART_COMPANY_EMAIL}. Website: {$SMART_WEBSITE}. Booking: {$SMART_BOOKING_LINK}. Mode: {$mode}. CUSTOMER SERVICE: {$customer}. ESTIMATING: {$estimate}. SITE KNOWLEDGE: {$site}. KNOWLEDGE FILES: {$knowledge}"; }
function smart_ai_curl(string $url,array $payload,string $key): array { $ch=curl_init($url); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_TIMEOUT=>45,CURLOPT_HTTPHEADER=>['Content-Type: application/json','Authorization: Bearer '.$key],CURLOPT_POSTFIELDS=>json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)]); $response=curl_exec($ch); $error=curl_error($ch); $code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE); curl_close($ch); return [$code,$response,$error]; }
function smart_ai_extract_responses(array $json): string { if(isset($json['output_text'])&&is_string($json['output_text'])){return trim($json['output_text']);} $reply=''; if(isset($json['output'])&&is_array($json['output'])){foreach($json['output'] as $item){if(isset($item['content'])&&is_array($item['content'])){foreach($item['content'] as $c){if(isset($c['text'])&&is_string($c['text'])){$reply.=$c['text']."\n";}}}}} return trim($reply); }
function smart_ai_extract_chat(array $json): string { return trim((string)($json['choices'][0]['message']['content'] ?? '')); }
if($_SERVER['REQUEST_METHOD']!=='POST'){ smart_ai_json(['ok'=>false,'reply'=>'Invalid request method.']); }
$raw=file_get_contents('php://input'); $data=json_decode($raw?:'',true); if(!is_array($data)){$data=$_POST;}
$message=trim((string)($data['message']??'')); $mode=trim((string)($data['mode']??'customer_service')); if($message===''){smart_ai_json(['ok'=>false,'reply'=>'Please type your question.']);}
if($mode==='auto'){$mode=smart_ai_detect_mode($message);} if(!in_array($mode,['customer_service','estimating','appointment'],true)){$mode=smart_ai_detect_mode($message);}
$local=smart_ai_local_reply($message,$mode,$SMART_BOOKING_LINK); if(empty($OPENAI_API_KEY)){smart_ai_log('Missing OpenAI key.'); smart_ai_json(['ok'=>true,'mode'=>$mode,'reply'=>$local]);}
$system=smart_ai_prompt($mode); $models=[]; foreach([$OPENAI_MODEL ?? '', 'gpt-4o-mini', 'gpt-4.1-mini'] as $m){$m=trim((string)$m); if($m!==''&&!in_array($m,$models,true)){$models[]=$m;}}
foreach($models as $model){ [$code,$resp,$err]=smart_ai_curl('https://api.openai.com/v1/responses',['model'=>$model,'input'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$message]],'max_output_tokens'=>650],$OPENAI_API_KEY); if($resp){$json=json_decode($resp,true); if(is_array($json)&&$code>=200&&$code<300){$reply=smart_ai_extract_responses($json); if($reply!==''){smart_ai_json(['ok'=>true,'mode'=>$mode,'reply'=>$reply]);}} smart_ai_log('Responses API '.$code.' '.$model.': '.(is_array($json)?($json['error']['message']??$resp):$resp));} else {smart_ai_log('Responses API empty '.$model.': '.$err);} }
foreach($models as $model){ [$code,$resp,$err]=smart_ai_curl('https://api.openai.com/v1/chat/completions',['model'=>$model,'messages'=>[['role'=>'system','content'=>$system],['role'=>'user','content'=>$message]],'max_tokens'=>650,'temperature'=>0.3],$OPENAI_API_KEY); if($resp){$json=json_decode($resp,true); if(is_array($json)&&$code>=200&&$code<300){$reply=smart_ai_extract_chat($json); if($reply!==''){smart_ai_json(['ok'=>true,'mode'=>$mode,'reply'=>$reply]);}} smart_ai_log('Chat API '.$code.' '.$model.': '.(is_array($json)?($json['error']['message']??$resp):$resp));} else {smart_ai_log('Chat API empty '.$model.': '.$err);} }
smart_ai_json(['ok'=>true,'mode'=>$mode,'reply'=>$local]);
